/*
 * prog55_connected_components
 *
 * The program receives its whole input on the command line.
 *
 *   argv[1] : number of vertices  (0 … 7)
 *   argv[2] : number of edges     (0 … 7)
 *   argv[3] … argv[2+2*m] : the edges, each given as a pair
 *                           (u v) with 0 ≤ u,v < n
 *
 * It builds an undirected adjacency matrix for a graph of at most
 * eight vertices, then prints each connected component in the form
 *
 *   0: {0,1,2}
 *   1: {3,4}
 *
 * (components are numbered starting from 0, vertices inside a
 * component are printed in the order they are discovered by a BFS).
 *
 * Any violation of the input constraints causes the program to print
 *   INVALID_INPUT
 * and exit with status 1.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8                     /* maximum number of vertices (0‑7) */

int main(int argc, char **argv)
{
    /* ---------- basic validation ---------- */
    if (argc < 3) {                     /* need at least n and m */
        puts("INVALID_INPUT");
        return 1;
    }

    /* read n (vertices) and m (edges) */
    int n = (int)strtol(argv[1], NULL, 10);
    int m = (int)strtol(argv[2], NULL, 10);

    if (n < 0 || n >= MAXV || m < 0 || m >= MAXV) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* we must have exactly 2*m numbers after n and m */
    if (argc != 3 + 2 * m) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* ---------- build adjacency matrix ---------- */
    int adj[MAXV][MAXV] = { {0} };

    for (int i = 0; i < m; ++i) {
        int u = (int)strtol(argv[3 + 2 * i],     NULL, 10);
        int v = (int)strtol(argv[3 + 2 * i + 1], NULL, 10);

        if (u < 0 || u >= n || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }

        adj[u][v] = 1;
        adj[v][u] = 1;          /* undirected graph */
    }

    /* ---------- BFS to find connected components ---------- */
    int visited[MAXV] = {0};
    int queue[MAXV];           /* simple queue – size is sufficient */
    int comp_id = 0;           /* component counter */

    for (int start = 0; start < n; ++start) {
        if (visited[start])
            continue;          /* already part of a previous component */

        /* start a new component */
        int qhead = 0, qtail = 0;
        queue[qtail++] = start;
        visited[start] = 1;

        printf("%d:", comp_id);
        printf(" {");

        int first = 1;         /* control commas */

        while (qhead < qtail) {
            int v = queue[qhead++];

            if (!first)
                putchar(',');
            printf("%d", v);
            first = 0;

            /* enqueue all unvisited neighbours of v */
            for (int w = 0; w < n; ++w) {
                if (adj[v][w] && !visited[w]) {
                    visited[w] = 1;
                    queue[qtail++] = w;
                }
            }
        }

        putchar('}');
        putchar('\n');
        ++comp_id;
    }

    return 0;
}
